package rates

import (
	"sync"
	"time"
)

type entry struct {
	quote   Quote
	expires time.Time
}

type flight struct {
	done  chan struct{}
	quote Quote
	err   error
}

// Cache keeps quotes for ttl so the provider is not called for every
// conversion. It is safe for concurrent use.
type Cache struct {
	mu       sync.Mutex
	ttl      time.Duration
	clock    Clock
	load     Loader
	entries  map[string]entry
	inflight map[string]*flight
}

func NewCache(load Loader, ttl time.Duration, clock Clock) *Cache {
	return &Cache{
		ttl:      ttl,
		clock:    clock,
		load:     load,
		entries:  make(map[string]entry),
		inflight: make(map[string]*flight),
	}
}

// Get returns the cached quote for pair, loading it when missing or expired.
func (c *Cache) Get(pair string) (Quote, error) {
	c.mu.Lock()
	if e, ok := c.entries[pair]; ok && c.clock.Now().Before(e.expires) {
		c.mu.Unlock()
		return e.quote, nil
	}
	if f, ok := c.inflight[pair]; ok {
		c.mu.Unlock()
		<-f.done
		return f.quote, f.err
	}
	f := &flight{done: make(chan struct{})}
	c.inflight[pair] = f
	c.mu.Unlock()

	f.quote, f.err = c.load(pair)

	c.mu.Lock()
	if f.err == nil {
		c.entries[pair] = entry{quote: f.quote, expires: c.clock.Now().Add(c.ttl)}
	}
	delete(c.inflight, pair)
	c.mu.Unlock()
	close(f.done)
	return f.quote, f.err
}

// Invalidate drops the cached quote for pair.
func (c *Cache) Invalidate(pair string) {
	c.mu.Lock()
	delete(c.entries, pair)
	c.mu.Unlock()
}
